mapper.select:
SELECT S.ID AS STAY_ID, S.BIZ_ID, S.NAME, S.PHONE, S.ZIPCODE, S.ADDR1, S.ADDR2, S.LAT, S.LNG, S.DESCRIPTION, S.TAGS, S.CHECKIN, S.CHECKOUT, S.PET_FEE, S.PET_POLICY, S.REFUND_POLICY, S.REGION, NVL(R.MIN_PRICE, 0) AS minPrice, NVL(R.ROOM_CNT, 0) AS roomCount,
FROM STAY S
WHERE S.ID = #{stayId}

SELECT S.ID AS STAY_ID, S.BIZ_ID, S.NAME, S.PHONE, S.ZIPCODE, S.ADDR1, S.ADDR2, S.LAT, S.LNG, S.DESCRIPTION, S.TAGS, S.CHECKIN, S.CHECKOUT, S.PET_FEE, S.PET_POLICY, S.REFUND_POLICY, S.REGION, NVL(R.MIN_PRICE, 0) AS minPrice, NVL(R.ROOM_CNT, 0) AS roomCount,
FROM STAY S JOIN BUSINESS B ON S.BIZ_ID = B.ID
WHERE B.MEMBER_ID = #{memberId}

SELECT S.ID AS STAY_ID, S.BIZ_ID, S.NAME, S.PHONE, S.ZIPCODE, S.ADDR1, S.ADDR2, S.LAT, S.LNG, S.DESCRIPTION, S.TAGS, S.CHECKIN, S.CHECKOUT, S.PET_FEE, S.PET_POLICY, S.REFUND_POLICY, S.REGION, NVL(R.MIN_PRICE, 0) AS minPrice, NVL(R.ROOM_CNT, 0) AS roomCount,
FROM STAY S
WHERE S.BIZ_ID = #{bizId}

mapper.update:
UPDATE STAY
NAME = #{name}, PHONE = #{phone, jdbcType=VARCHAR}, ZIPCODE = #{zipcode, jdbcType=VARCHAR}, ADDR1 = #{addr1, jdbcType=VARCHAR}, ADDR2 = #{addr2, jdbcType=VARCHAR}, LAT = #{lat, jdbcType=DOUBLE}, LNG = #{lng, jdbcType=DOUBLE}, TAGS = #{tags, jdbcType=VARCHAR}, DESCRIPTION = #{description, jdbcType=VARCHAR}, CHECKIN = #{checkIn, jdbcType=DATE}, CHECKOUT = #{checkOut, jdbcType=DATE}, PET_FEE = #{petFee, jdbcType=NUMERIC}, PET_POLICY = #{petPolicy, jdbcType=VARCHAR}, REFUND_POLICY = #{refundPolicy, jdbcType=VARCHAR}, REGION = #{region, jdbcType=VARCHAR}
WHERE ID = #{stayId}

UPDATE ROOM
NAME = #{name}, PRICE = #{price, jdbcType=NUMERIC}, MAXPEOPLE = #{maxPeople, jdbcType=NUMERIC}, MAXPET = #{maxPet, jdbcType=NUMERIC},
WHERE ID = #{roomId} AND STAY_ID = #{stayId}
